const results = [];

for (const item of $input.all()) {
  let raw = item.json.output;
  let score = null;
  let decision = null;

  if (typeof raw === 'string') {
    let cleaned = raw.replace(/```json|```/g, '').trim();
    const firstBrace = cleaned.indexOf('{');
    const lastBrace = cleaned.lastIndexOf('}');

    if (firstBrace !== -1 && lastBrace !== -1) {
      try {
        const jsonPart = cleaned.substring(firstBrace, lastBrace + 1);
        const data = JSON.parse(jsonPart);
        score = data.total_score;
        decision = data.decision;
      } catch (e) {
        // fall through to text-based extraction below
      }
    }

    if (score === null || decision === null) {
      const scoreMatch = cleaned.match(/(?:Total Score|total_score)[:\s]*\**\s*(\d+)/i);
      const decisionMatch = cleaned.match(/(?:Decision)[:\s]*\**\s*(SHORTLISTED|DISQUALIFIED)/i);

      score = scoreMatch ? parseInt(scoreMatch[1], 10) : 0;
      decision = decisionMatch ? decisionMatch[1].toUpperCase() : 'DISQUALIFIED';
    }
  } else {
    score = raw.total_score;
    decision = raw.decision;
  }

  results.push({
    json: { score, decision }
  });
}

return results;
